<section class="container section-top"><?php ff_heading($kind??$page,t($intro??'Find your focus and explore the details.')); ?><form class="filter-bar" method="get"><input type="hidden" name="page" value="<?=e($page)?>"><input type="hidden" name="lang" value="<?=e($lang)?>"><label class="search-field"><span><?=e(t('search'))?></span><div><?=ff_icon('search')?><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="<?=e(t('search'))?>" maxlength="100"></div></label><label><span><?=e(t('category'))?></span><select name="category"><option value=""><?=e(t('all_categories'))?></option><?php foreach($categories??[] as $category): $value=is_array($category)?($category['category']??''):$category; ?><option value="<?=e($value)?>" <?=($_GET['category']??'')===$value?'selected':''?>><?=e(t($value))?></option><?php endforeach ?></select></label><?php if(($kind??'')==='services'): ?><label><span><?=e(t('difficulty'))?></span><select name="level"><option value=""><?=e(t('all_levels'))?></option><?php foreach(['beginner','intermediate','all_levels'] as $v): ?><option value="<?=e($v)?>" <?=($_GET['level']??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach ?></select></label><label><span><?=e(t('format'))?></span><select name="format"><option value=""><?=e(t('all_formats'))?></option><?php foreach(['individual','group','self-guided'] as $v): ?><option value="<?=e($v)?>" <?=($_GET['format']??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach ?></select></label><?php endif ?><button class="button dark"><?=e(t('filter'))?></button><a class="text-link" href="<?=e(url($page))?>"><?=e(t('clear_filters'))?></a></form><div class="results-caption"><span><?=e((string)($total??count($items??[])))?> <?=e(t('results'))?></span><span><?=e(t('Thoughtfully selected. Clearly explained.'))?></span></div><div class="card-grid three"><?php foreach($items??[] as $item) ff_card($item); ?></div><?php if(empty($items))ff_empty(); ff_pagination($pages??1,$pageNumber??1,$page); ?></section>
